-- 2026-10-31f: MP Background timelines for 26 select committee chairs, batch 6 (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (353 entries, copied exactly from the batch 6 data file, which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 40, 1171, 1442, 1524, 1536, 3952, 4005, 4008, 4061, 4110, 4124, 4267, 4389, 4436, 4439, 4494, 4510, 4612, 4623, 4638, 4656, 4716, 4820, 5143, 5190, 5337,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate() (source links were
-- not rechecked in this job). Nothing else changes. No code change. Backup of the 26 rows, off the repo:
-- "Claude outputs/backups/2026-10-31f-mp-biography-before.csv".
-- Guards (RAISE): exactly 26 rows change, all of them these 26; the 70 existing timelines are unchanged (md5);
-- MPs with a timeline go from 70 to 96; each array equals the file exactly; 1320 entries in all afterwards.
-- Undo: 2026-10-31f-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (40, 1171, 1442, 1524, 1536, 3952, 4005, 4008, 4061, 4110, 4124, 4267, 4389, 4436, 4439, 4494, 4510, 4612, 4623, 4638, 4656, 4716, 4820, 5143, 5190, 5337)) <> 26 THEN RAISE EXCEPTION 'expected 26 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (40, 1171, 1442, 1524, 1536, 3952, 4005, 4008, 4061, 4110, 4124, 4267, 4389, 4436, 4439, 4494, 4510, 4612, 4623, 4638, 4656, 4716, 4820, 5143, 5190, 5337) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a batch 6 MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 70 THEN RAISE EXCEPTION 'expected 70 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
