  (4267, 12, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Prince William School, Oundle","detail":"She attended the school after moving to Northamptonshire.","source":{"title":"Politics.co.uk: Sarah Champion","url":"https://www.politics.co.uk/people/sarah-champion/"}},{"phase":"education","start":null,"end":"1991","title":"BA Psychology","organisation":"University of Sheffield","detail":"She graduated with a BA degree in psychology in 1991.","source":{"title":"Wikipedia: Sarah Champion","url":"https://en.wikipedia.org/wiki/Sarah_Champion"}},{"phase":"career","start":null,"end":null,"title":"Volunteer","organisation":"St Luke's Hospice, Sheffield","detail":"She worked as a volunteer at the hospice and ran art workshops at a Sheffield secondary school.","source":{"title":"Wikipedia: Sarah Champion","url":"https://en.wikipedia.org/wiki/Sarah_Champion"}},{"phase":"career","start":null,"end":null,"title":"Art and environment workshop leader","organisation":"Rotherham Borough Council","detail":"She ran art and environment workshops in schools and libraries after graduating.","source":{"title":"Sarah Champion MP: Biography","url":"https://www.sarahchampionmp.com/about-sarah"}},{"phase":"career","start":null,"end":"1994","title":"Ran Rotherham Arts Centre","organisation":"Rotherham Arts Centre","detail":"Her first full time employment was running the arts centre.","source":{"title":"Sarah Champion MP: Biography","url":"https://www.sarahchampionmp.com/about-sarah"}},{"phase":"career","start":"1994","end":null,"title":"Arts worker","organisation":"Ashfield District Council","detail":null,"source":{"title":"Sarah Champion MP: Biography","url":"https://www.sarahchampionmp.com/about-sarah"}},{"phase":"career","start":"1996","end":"2008","title":"Chief Executive","organisation":"Chinese Arts Centre, Manchester","detail":"The centre was an international agency promoting contemporary arts and culture.","source":{"title":"Sarah Cham